    "summary": "If an ADEPTUS ASTARTES unit has a second Faction keyword on its datasheet, that Faction keyword is the name of that unit's Chapter. You cannot include units from more than one Chapter in your army. The rules in this book can also represent a Blood Angels successor Chapter, but BLOOD ANGELS EPIC HEROES represent the First Founding Chapter itself.",
